// Exact four-kernel-direction prototype; explicit finite quartet subset.
#include <algorithm>
#include <array>
#include <chrono>
#include <cmath>
#include <csignal>
#include <cstdint>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <sys/resource.h>
#include <unordered_set>
#include <utility>
#include <vector>
using U=uint64_t;using V=std::vector<uint32_t>;using Column=std::array<U,10>;
static volatile std::sig_atomic_t stopped=0;static void stop_handler(int){stopped=1;}
static void atomic_text(const std::string&path,const std::string&data){auto p=std::filesystem::path(path);if(p.has_parent_path())std::filesystem::create_directories(p.parent_path());std::ofstream f(path+".tmp");if(!f)throw std::runtime_error("cannot write");f<<data;f.close();if(!f)throw std::runtime_error("write failed");std::filesystem::rename(path+".tmp",path);}
static void write_vectors(const std::string&path,const V&v){std::ostringstream s;for(auto x:v)s<<x<<'\n';atomic_text(path,s.str());}
#include <unordered_map>
#include <set>
struct Options {std::string input,output,catalog,input_sha,baseline_sha,catalog_sha;double seconds=600,checkpoint=15;int target=92;U start=0,max_quartets=0;};
static Options options(int argc,char**argv){Options o;for(int k=1;k<argc;++k){std::string key=argv[k];if(k+1==argc)throw std::runtime_error("missing option value");std::string v=argv[++k];
if(key=="--input")o.input=v;else if(key=="--output")o.output=v;else if(key=="--catalog")o.catalog=v;else if(key=="--seconds")o.seconds=std::stod(v);else if(key=="--target")o.target=std::stoi(v);else if(key=="--start-row")o.start=std::stoull(v);else if(key=="--max-quartets")o.max_quartets=std::stoull(v);else if(key=="--checkpoint-seconds")o.checkpoint=std::stod(v);else if(key=="--input-sha256")o.input_sha=v;else if(key=="--baseline-sha256")o.baseline_sha=v;else if(key=="--catalog-sha256")o.catalog_sha=v;else throw std::runtime_error("unknown option "+key);}
if(o.input.empty()||o.output.empty()||o.catalog.empty()||!std::isfinite(o.seconds)||o.seconds<0||!std::isfinite(o.checkpoint)||o.checkpoint<=0||o.target<0)throw std::runtime_error("invalid options");
for(auto&s:{o.input_sha,o.baseline_sha,o.catalog_sha})if(!s.empty()&&(s.size()!=64||s.find_first_not_of("0123456789abcdef")!=std::string::npos))throw std::runtime_error("invalid hash");
return o;}
#include "kernel_quartet_optimizer.hpp"
int main(int argc,char**argv){Options o;try{o=options(argc,argv);rlimit limit{768ULL*1024*1024,768ULL*1024*1024};if(setrlimit(RLIMIT_AS,&limit))throw std::runtime_error("memory limit failed");
std::ifstream in(o.input);std::string magic;int n,p,c;std::array<int,3> perm{};if(!(in>>magic>>n>>p>>c)||magic!="MMKERNELWIDE1"||n<2||n>5||p<1||p>10000||c<4||c>50000)throw std::runtime_error("invalid header");if(!(in>>perm[0]>>perm[1]>>perm[2]))throw std::runtime_error("missing permutation");auto sorted=perm;std::sort(sorted.begin(),sorted.end());if(sorted!=std::array<int,3>{0,1,2})throw std::runtime_error("invalid permutation");
int width=n*n;U bound=U(1)<<width;V baseline(p);std::vector<Column> columns(p);std::vector<std::vector<int>> rows(p);std::unordered_set<U> unique_pairs;
for(int g=0;g<p;++g){U a,b,w;if(!(in>>a>>b>>w)||!a||!b||a>=bound||b>=bound||w>=bound)throw std::runtime_error("invalid pair/model");if(!unique_pairs.insert((a<<25)|b).second)throw std::runtime_error("duplicate pair");baseline[g]=w;columns[g].fill(0);for(U x=a;x;x&=x-1)for(U y=b;y;y&=y-1){int r=__builtin_ctzll(x)*width+__builtin_ctzll(y);columns[g][r/64]^=U(1)<<(r%64);rows[g].push_back(r);}}
std::vector<std::vector<int>> supports(c);std::set<std::vector<int>> unique_supports;for(int k=0;k<c;++k){int kind,size;if(!(in>>kind>>size)||kind<0||kind>2||size<3||size>128||(kind==0&&size!=3)||(kind==1&&size!=4))throw std::runtime_error("invalid wide circuit");Column total{};std::unordered_set<int> distinct;for(int j=0;j<size;++j){int g;if(!(in>>g)||g<0||g>=p||!distinct.insert(g).second)throw std::runtime_error("invalid group");supports[k].push_back(g);for(int x=0;x<10;++x)total[x]^=columns[g][x];}if(std::any_of(total.begin(),total.end(),[](U x){return x;}))throw std::runtime_error("nonkernel circuit rejected");std::sort(supports[k].begin(),supports[k].end());if(!unique_supports.insert(supports[k]).second)throw std::runtime_error("duplicate circuit");}std::string extra;if(in>>extra)throw std::runtime_error("trailing input");
V target(width*width);for(int i=0;i<n;++i)for(int j=0;j<n;++j)for(int k=0;k<n;++k){std::array<int,3> xyz{i*n+j,j*n+k,k*n+i};target[xyz[perm[0]]*width+xyz[perm[1]]]^=uint32_t(1)<<xyz[perm[2]];}auto check=[&](const V&w){V observed(width*width);for(int g=0;g<p;++g){if(w[g]>=bound)throw std::runtime_error("mask out of range");if(w[g])for(int r:rows[g])observed[r]^=w[g];}if(observed!=target)throw std::runtime_error("original PW=Y failed");};check(baseline);
std::ifstream cat(o.catalog);U total;if(!(cat>>magic>>total)||magic!="MMKQUARTETS1"||total>2000000||o.start>total)throw std::runtime_error("invalid finite quartet catalog");std::vector<std::array<int,4>> quartets(total);std::set<std::array<int,4>> seen;for(auto&t:quartets){if(!(cat>>t[0]>>t[1]>>t[2]>>t[3])||t[0]<0||t[0]>=t[1]||t[1]>=t[2]||t[2]>=t[3]||t[3]>=c||!seen.insert(t).second)throw std::runtime_error("invalid/duplicate quartet row");}if(cat>>extra)throw std::runtime_error("trailing catalog");
int baseline_rank=std::count_if(baseline.begin(),baseline.end(),[](uint32_t x){return x;});V best=baseline;int best_rank=baseline_rank;U considered=0,bound_pruned=0,exact=0,candidates=0,workload=0,next=o.start;std::string status="RUNNING",reason="";auto all=quartet::make_bases();auto start=std::chrono::steady_clock::now();auto deadline=start+std::chrono::duration_cast<std::chrono::steady_clock::duration>(std::chrono::duration<double>(o.seconds));auto elapsed=[&](){return std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();};
auto checkpoint=[&](){check(best);write_vectors(o.output+".best.w.txt",best);write_vectors(o.output+".current.w.txt",best);std::ostringstream s;s<<"{\"engine\":\"exact-four-kernel-block-wide-v1\",\"status\":\""<<status<<"\",\"reason\":\""<<reason<<"\",\"baseline_rank\":"<<baseline_rank<<",\"best_rank\":"<<best_rank<<",\"current_rank\":"<<best_rank<<",\"target_rank\":"<<o.target<<",\"target_reached\":"<<(best_rank<=o.target?"true":"false")<<",\"linear_exact\":true,\"tensor_invariant_checked\":true,\"full_matrix_verified\":false,\"steps\":"<<considered<<",\"quartets_total\":"<<total<<",\"quartets_considered\":"<<considered<<",\"prefix_rows_skipped\":"<<o.start<<",\"next_row\":"<<next<<",\"bound_pruned\":"<<bound_pruned<<",\"exact_evaluated\":"<<exact<<",\"full_basis_rhs_workload\":"<<workload<<",\"candidate_assignments\":"<<candidates<<",\"elapsed_seconds\":"<<elapsed()<<",\"input_sha256\":\""<<o.input_sha<<"\",\"catalog_sha256\":\""<<o.catalog_sha<<"\",\"baseline_sha256\":\""<<o.baseline_sha<<"\"}\n";atomic_text(o.output+".stats.json",s.str());};
std::signal(SIGTERM,stop_handler);std::signal(SIGINT,stop_handler);checkpoint();double next_checkpoint=o.checkpoint;
if(best_rank<=o.target){status="MODEL_FOUND";reason="baseline already meets target";}else for(;next<total;){if(stopped||std::chrono::steady_clock::now()>=deadline||(o.max_quartets&&considered>=o.max_quartets)){status="UNKNOWN";reason=stopped?"interrupted":"wall or quartet budget";break;}auto t=quartets[next];quartet::Bags bags;std::unordered_map<int,int> memberships;for(int j=0;j<4;++j)for(int g:supports[t[j]])memberships[g]|=1<<j;for(auto entry:memberships)bags[entry.second].add(baseline[entry.first]);
int zeros=0,upper=0;for(int s=1;s<16;++s){zeros+=bags[s].zeros;upper+=bags[s].maximum;}quartet::Opt opt;bool hit=false;if(baseline_rank+zeros-upper>o.target)++bound_pruned;else{++exact;opt=quartet::optimize_components(bags,all,deadline,&stopped);candidates+=opt.candidates;workload+=opt.workload;if(!opt.complete){status="UNKNOWN";reason="interrupted inside exact quartet";break;}hit=baseline_rank+opt.zeros-opt.score<=o.target;}

++considered;++next;if(hit){V moved=baseline;for(int j=0;j<4;++j)for(int g:supports[t[j]])moved[g]^=opt.move[j];check(moved);best_rank=std::count_if(moved.begin(),moved.end(),[](uint32_t x){return x;});if(best_rank>o.target)throw std::runtime_error("objective/rank mismatch");best=moved;std::ostringstream proof;proof<<"{\"circuit_i\":"<<t[0]<<",\"circuit_j\":"<<t[1]<<",\"circuit_k\":"<<t[2]<<",\"circuit_l\":"<<t[3]<<",\"d\":"<<opt.move[0]<<",\"e\":"<<opt.move[1]<<",\"f\":"<<opt.move[2]<<",\"g\":"<<opt.move[3]<<",\"before_rank\":"<<baseline_rank<<",\"after_rank\":"<<best_rank<<",\"linear_verified\":true}\n";atomic_text(o.output+".solution.json",proof.str());status="MODEL_FOUND";reason="pending independent global verification";break;}if(elapsed()>=next_checkpoint){checkpoint();next_checkpoint=elapsed()+o.checkpoint;}}
if(status=="RUNNING"){status="NO_TARGET";reason="finite supplied quartet suffix exhausted";}checkpoint();std::cout<<status<<" quartets="<<considered<<" best_rank="<<best_rank<<'\n';return 0;
}catch(const std::exception&e){if(!o.output.empty())try{atomic_text(o.output+".stats.json","{\"status\":\"ERROR\",\"reason\":\"native validation or IO failure\"}\n");}catch(...){}std::cerr<<"quartet_block_worker_wide: "<<e.what()<<'\n';return 1;}}
